const int segPins[7] = {2, 3, 4, 5, 6, 7, 8};
byte digits[10] = {
  B0111111, B0000110, B1011011, B1001111, B1100110,
  B1101101, B1111101, B0000111, B1111111, B1101111
};

void setup() {
  for (int i = 0; i < 7; i++) pinMode(segPins[i], OUTPUT);
}

void loop() {
  for (int d = 0; d < 10; d++) {
    for (int s = 0; s < 7; s++) {
      digitalWrite(segPins[s], bitRead(digits[d], s));
    }
    delay(1000);
  }
}
